using Godot;

// Everything ShaderWarmup draws. Generated by the editor tool (Project > Tools > Rebuild Shader
// Warm-up Manifest) - never edited by hand. Paths rather than resources, so loading the manifest
// doesn't load every effect in the game in one frame.
[GlobalClass]
public partial class ShaderWarmupManifest : Resource
{
    public const string FilePath = "res://core/shader_warmup_manifest.tres";

    [Export] public string[] ScenePaths { get; set; } = [];
    [Export] public string[] MaterialPaths { get; set; } = [];
    [Export] public string[] ShaderPaths { get; set; } = [];
}
